// Extract renewal data
const input = $input.first().json;
const body = input.body || {};
const data = body.data || {};

if (!data.subscription_id) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Missing subscription_id',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Convert Unix timestamps to ISO
const periodEnd = data.period_end 
  ? new Date(data.period_end * 1000).toISOString()
  : null;

return [{
  json: {
    valid: true,
    stripe_subscription_id: data.subscription_id,
    stripe_customer_id: data.customer_id,
    invoice_id: data.invoice_id,
    amount_paid: data.amount_paid || 0,
    currency: data.currency || 'eur',
    period_end: periodEnd,
    period_start: data.period_start,
    billing_reason: data.billing_reason || 'subscription_cycle',
    event_id: body.event_id
  }
}];

// Determine credits to add based on plan
const subscriber = $input.first().json;
const prevData = $('Extract Data').first().json;

if (!subscriber || !subscriber.id) {
  return [{
    json: {
      found: false,
      error: 'Subscriber not found for subscription: ' + prevData.stripe_subscription_id
    }
  }];
}

const plan = subscriber.subscription_plan || 'basic';
const creditsMap = {
  'basic': 1000,
  'premium': 5000,
  'unlimited': 999999
};
const creditsToAdd = creditsMap[plan] || 1000;

return [{
  json: {
    found: true,
    user_id: subscriber.id,
    discord_user_id: subscriber.discord_user_id,
    plan: plan,
    current_credits: subscriber.credits,
    credits_to_add: creditsToAdd,
    stripe_subscription_id: prevData.stripe_subscription_id,
    stripe_customer_id: prevData.stripe_customer_id,
    invoice_id: prevData.invoice_id,
    amount_paid: prevData.amount_paid,
    currency: prevData.currency,
    period_end: prevData.period_end,
    event_id: prevData.event_id
  }
}];

// Prepare success response
const calcData = $('Calculate Credits').first().json;
const newCredits = $('Add Credits').first().json?.credits || (calcData.current_credits + calcData.credits_to_add);

return [{
  json: {
    success: true,
    processed: true,
    discord_user_id: calcData.discord_user_id,
    plan: calcData.plan,
    credits_added: calcData.credits_to_add,
    new_credits: newCredits
  }
}];
